void rsr_stop (void * arg)
{
	os_flg_clr (rsr_vars.flg_start) ;
	os_flg_set (rsr_vars.flg_stop)  ; 

  rf_icon_clr  (ICON_SUCCESS , FALSE) ;
	rf_icon_clr  (ICON_STARTED , TRUE)  ;
}

